INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-ridge', 'south', 'the-ridge-cave-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ridge-cave-mouth', 'door', 'The Cave Under the Ridge', 'The ridge breaks open at its foot into a mouth of grey rock higher than a man, with ferns hanging over the lip and the ground inside trodden bare. The light goes in a dozen paces and gives up. The air coming out of it is cold and smells of earth, and under the earth, of animal.', 0, 0, 'wood', 0, -50, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-mouth', 'north', 'the-green-ridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-mouth', 'south', 'the-ridge-cave-drop', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ridge-cave-drop', 'door', 'The Drop', 'The floor steps down a man''s height in a slope of broken stone, polished on the left where something heavy has always gone down it the same way. The roof closes in overhead. Behind you the mouth is a grey shape that no longer lights anything.', 0, 0, 'wood', 0, -50, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-drop', 'north', 'the-ridge-cave-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-drop', 'south', 'the-ridge-cave-fork', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ridge-cave-fork', 'door', 'The Fork', 'The passage splits around a pillar of rock worn smooth at shoulder height on both sides, and greasy with it. One way goes on down. The other is a short low hole off to the west, and the smell is stronger from neither and from both.', 0, 0, 'wood', 0, -50, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-fork', 'north', 'the-ridge-cave-drop', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-fork', 'west', 'the-ridge-cave-pocket', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-fork', 'south', 'the-ridge-cave-squeeze', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ridge-cave-pocket', 'door', 'The Bone Pocket', 'A dead end the size of a cart, floored with bones. Deer, mostly, by the shape of the skulls, and boar, and none of them recent: they have been dragged in here and gone over and left, and the newest are no newer than a season. It is a larder, and it is a long way down a bad passage from the light.', 0, 0, 'wood', 0, -51, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-pocket', 'east', 'the-ridge-cave-fork', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ridge-cave-squeeze', 'door', 'The Squeeze', 'The roof comes down to meet the floor and the passage goes on between them, flat and wide, and you go through it bent double with the rock touching your back. Hair is caught on it here and there, coarse and brown and long. Something much bigger than you comes through here and does not find it a squeeze at all.', 0, 0, 'wood', 0, -50, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-squeeze', 'north', 'the-ridge-cave-fork', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave-squeeze', 'south', 'the-ridge-cave', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ridge-cave', 'door', 'The Ridge Cave', 'The roof lifts away into the dark and the passage opens into a chamber that swallows any light you bring. The floor is dry and soft with years of bracken carried in and trodden down, and the walls are scored in long parallel grooves as high as you can reach and higher. This is the back of the ridge, and the deepest place in it, and it is where the bear sleeps.', 0, 0, 'wood', 0, -50, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave', 'north', 'the-ridge-cave-squeeze', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-oak', 'north', 'the-oak-cave-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-cave-mouth', 'door', 'The Mouth Under the Oak', 'The oak has grown down over a split in the rock and held it, and the split goes back under the tree into the dark. Roots as thick as your leg come through the roof of it. The earth at the threshold is churned and printed, and the bark of the oak beside it is clawed through to the wood.', 0, 0, 'wood', 0, -52, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-mouth', 'south', 'the-stone-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-mouth', 'north', 'the-oak-cave-crawl', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-cave-crawl', 'door', 'The Root Crawl', 'A low crawl under the roots, half earth and half stone, where the oak''s underneath comes down through the ceiling in ropes you have to push past. It is close and warm and it smells of fur. There is no room in here to turn around in a hurry.', 0, 0, 'wood', 0, -52, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-crawl', 'south', 'the-oak-cave-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-crawl', 'north', 'the-oak-cave-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-cave-hall', 'door', 'The Low Hall', 'The crawl opens into a low wide hall of stone with a floor of dry dirt, roofed so close you could lay your hand flat on it. The dirt is dug over in great scoops in one corner where something has been making a bed and thinking better of it. The way on goes off west, narrower.', 0, 0, 'wood', 0, -52, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-hall', 'south', 'the-oak-cave-crawl', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-hall', 'west', 'the-oak-cave-neck', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-cave-neck', 'door', 'The Neck', 'A short throat of rock between the hall and whatever is beyond, so narrow that the sides are polished brown with the passing of a broad body. A single bone lies in the middle of it, cracked for the marrow and put down.', 0, 0, 'wood', 0, -53, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-neck', 'east', 'the-oak-cave-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave-neck', 'north', 'the-oak-cave', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-cave', 'door', 'The Oak Cave', 'A round chamber at the end of everything, under the rock and under the oak both, with the roots coming down out of the dark overhead and into the floor like the bars of something. The bed is here against the far wall, a heap of bracken and leaves pressed into the shape of a body. It is the warmest room in the wood and it is not warm for you.', 0, 0, 'wood', 0, -53, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-cave', 'south', 'the-oak-cave-neck', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-wall', 'north', 'the-wall-cave-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wall-cave-mouth', 'door', 'The Breach', 'Behind where the wall came down the hillside is hollow: the fall opened a hole into the rock that the wall had been built across, and nobody was left to wall it up again. Cut stones lie tumbled in the mouth, and the dark goes on past them. Something has made a path through the tumble that is not your width.', 0, 0, 'wood', 0, -32, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave-mouth', 'south', 'the-fallen-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave-mouth', 'north', 'the-wall-cave-passage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wall-cave-passage', 'door', 'The Dry Passage', 'A dry passage of pale rock, straight for a few paces as if it had been cut once and then left to the animals. The floor is dust, and the dust is printed over and over with broad five-toed feet coming and going. The way turns east ahead.', 0, 0, 'wood', 0, -32, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave-passage', 'south', 'the-wall-cave-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave-passage', 'east', 'the-wall-cave-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wall-cave-turn', 'door', 'The Turn', 'The passage bends and drops, and the cold comes up from below with the smell on it. A tree root has found its way down through a crack here and been torn out and left in pieces. The way goes on down, to the north.', 0, 0, 'wood', 0, -31, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave-turn', 'west', 'the-wall-cave-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave-turn', 'north', 'the-wall-cave', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wall-cave', 'door', 'The Wall Cave', 'A low chamber with a sandy floor and a roof that drips in one corner into a hollow worn in the rock. The bed is a long scrape in the sand lined with dead grass and the hair that came off whatever lay in it. The walls are scored deep. It is quiet in here in a way that has nothing to do with being empty.', 0, 0, 'wood', 0, -31, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wall-cave', 'south', 'the-wall-cave-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-boundary-stone', 'south', 'the-boundary-cave-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boundary-cave-mouth', 'door', 'The Hole Behind the Stone', 'The ground falls away behind the old stone into a hollow, and at the back of the hollow is a hole in the rock that the stone and the oak between them have been hiding. Moss on the lip is torn off in strips. A smell of old meat and wet fur hangs in it and does not move.', 0, 0, 'wood', 0, -47, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cave-mouth', 'north', 'the-old-boundary-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cave-mouth', 'south', 'the-boundary-cave-slope', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boundary-cave-slope', 'door', 'The Slope', 'The floor slants down and away under a roof of tilted rock, slick with leaf mould carried in on something''s feet. There are claw marks in the slope where it climbs out, gouged in to keep its footing. It goes down east into a wider dark.', 0, 0, 'wood', 0, -47, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cave-slope', 'north', 'the-boundary-cave-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cave-slope', 'east', 'the-boundary-cave', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boundary-cave', 'door', 'The Boundary Cave', 'A chamber like the inside of a fist, the rock closing all round and the roof low. The floor is a bed: a trodden mat of bracken and torn moss that fills it wall to wall, matted with hair. Whatever line the stone above once marked, this was the far side of it, and still is.', 0, 0, 'wood', 0, -46, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cave', 'west', 'the-boundary-cave-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-pile', 'east', 'the-pile-cave-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pile-cave-mouth', 'door', 'The Gap in the Stones', 'Two of the great stones in the pile lean together and leave a gap under them, black, the height of a crouching man. The ground in front of it is bare and beaten, and there is a smell coming out of it that the rest of the wood does not have.', 0, 0, 'wood', 0, -33, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pile-cave-mouth', 'west', 'the-stone-pile', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pile-cave-mouth', 'east', 'the-pile-cave', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pile-cave', 'door', 'The Pile Cave', 'Under the stones it is one small cave, the stones'' weight over your head and their cold all round, and room enough for one bed and not much else. The bed is there, a nest of leaves and bracken pressed flat, and the stones by it are rubbed smooth and dark where a body has leaned on them a long time.', 0, 0, 'wood', 0, -32, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pile-cave', 'west', 'the-pile-cave-mouth', NULL);
